import {ReactionRateEngine} from './engines.js';
import {chart,ParticleView,fmt} from './visuals.js';
import {esc} from './state.js';
export function mountActivity(host,id,state,{record,allState,save,isUnlocked}){
 if(id===1){const cases=[['一瞬到數秒','火柴燃燒','燃燒時，反應物快速減少，生成氣體並放出光與熱。','♨'],['數秒到數分鐘','碳酸鈣與酸','可用收集 CO₂ 的體積，記錄每段時間產生多少氣體。','◌'],['數小時到數天','食物氧化變質','某些氧化使顏色、氣味改變；腐敗也可能包含微生物作用。','◒'],['數天到更久','鐵釘生鏽','逐漸生成鐵鏽，通常需要水與氧；環境會影響速度。','⌁']];const seen=new Set();host.innerHTML=`<div class="scale-heading"><span class="step-label">時間尺度觀察台</span><h3>化學變化，有自己的步調</h3><p>點開四個案例，比較可觀察的變化。時間為常見量級，不是每次實驗的固定值。</p></div><div class="time-scale">${cases.map((c,i)=>`<button data-case="${i}" aria-pressed="false"><span class="time-glyph">${c[3]}</span><small>${c[0]}</small><b>${c[1]}</b><span>觀察 →</span></button>`).join('')}</div><p class="scale-arrow">通常較快 <span>───────────────── →</span> 通常較慢</p><div class="observation-status" role="status" data-info>選一個反應，看看能測量什麼。0 / 4 已觀察</div><div class="rate-formula"><b>把「快」變成可比較的數字</b><span>20 秒收集 100 mL 氣體</span><strong>100 mL ÷ 20 s ＝ 5 mL/s</strong><small>這是 0～20 秒的平均速率，不表示每一秒都剛好 5 mL。</small></div>`;host.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>{seen.add(Number(b.dataset.case));b.setAttribute('aria-pressed','true');host.querySelector('[data-info]').textContent=cases[Number(b.dataset.case)][2]+`　${seen.size} / 4 已觀察`;if(seen.size===4)record('scale');}));}
 if(id===3){host.innerHTML=`<div class="particle-study"><div><span class="step-label">微觀觀察 · 先看機會，再看結果</span><h3>不是每次碰撞，都能反應</h3><div class="view-tabs"><button data-condition="normal" aria-pressed="true">原始條件</button><button data-condition="dense" aria-pressed="false">提高濃度</button><button data-condition="surface" aria-pressed="false">磨細固體</button></div><canvas aria-label="粒子碰撞與反應表面示意"></canvas><div class="collision-key"><span>● 移動的反應粒子</span><span>▰ 固體的反應表面</span><span class="collision-spark">✦ 有效碰撞的觀念提示</span></div><p data-collision>不是每次碰到都能反應。畫面中的運動只用來呈現碰撞機會。</p><button class="text-button" data-pause>暫停微觀動畫</button></div><div class="nature-study"><span class="step-label">相同稀鹽酸，換一種金屬</span><h3>材料本身，也很重要</h3><p>固定酸濃度、溫度，選相近表面積比較。點開三個樣本。</p><div class="metal-samples">${[['Mg','鎂'],['Zn','鋅'],['Cu','銅']].map(([s,n])=>`<button data-metal="${s}" aria-pressed="false"><i class="metal-${s}"></i><b>${s}</b><span>${n}</span></button>`).join('')}</div><p class="observation-status" data-nature>選擇一種金屬查看反應。</p></div></div>`;const pv=new ParticleView(host.querySelector('canvas'));let cond='normal',time=0,paused=false;const seen=new Set(),metals=new Set();const text={normal:'一般濃度：有些碰撞可以反應，有些不行。',dense:'同體積中粒子更多，碰撞機會通常提高；不代表每次都成功。',surface:'固體總量相同，切成小塊後有更多可接觸的表面。'};host.querySelectorAll('[data-condition]').forEach(b=>b.addEventListener('click',()=>{cond=b.dataset.condition;seen.add(cond);host.querySelectorAll('[data-condition]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));host.querySelector('[data-collision]').textContent=text[cond];if(seen.has('dense')&&seen.has('surface'))record('collision');}));host.querySelectorAll('[data-metal]').forEach(b=>b.addEventListener('click',()=>{metals.add(b.dataset.metal);b.setAttribute('aria-pressed','true');host.querySelector('[data-nature]').textContent={Mg:'鎂：與稀鹽酸反應較快，可生成氫氣。',Zn:'鋅：在這個比較條件下比鎂慢，也可生成氫氣。',Cu:'銅：與這裡的稀鹽酸不產生排出氫氣的反應。不是所有金屬都相同。'}[b.dataset.metal]+`　${metals.size} / 3 已觀察`;if(metals.size===3)record('nature');}));host.querySelector('[data-pause]').addEventListener('click',e=>{paused=!paused;e.target.textContent=paused?'繼續微觀動畫':'暫停微觀動畫';});const tick=setInterval(()=>{if(!isUnlocked()||paused||host.getBoundingClientRect().bottom<0||host.getBoundingClientRect().top>innerHeight)return;time+=.12;pv.draw({time,temperature:20},{mode:'collision',surface:cond==='surface'?4:1,concentration:cond==='dense'?2:1});host.querySelector('.collision-spark').style.opacity=String(.4+.6*Math.abs(Math.sin(time*(cond==='normal'?1:2.8))));},120);pv.draw({time:0},{mode:'collision'});return()=>clearInterval(tick);}
 if(id===6){let selectedA=0,selectedB=1,viewed=new Set();const gather=()=>[2,4,5].flatMap(k=>allState.cards[k].records.map(r=>({...r,label:`卡 ${k} · ${r.label}`}))).filter(r=>r.curve?.[0]?.volume!==undefined);const example=[20,60].map((end,i)=>{const e=new ReactionRateEngine();e.k=1/(.35*end);e.endTime=end;e.capacity=100/24;return {label:'示例'+(i?'乙':'甲')+' · '+end+' 秒到 100 mL',curve:e.curve().map(s=>({time:s.time,volume:s.volume})),final:100,t90:e.timeFor(.9)};});
 function draw(){let records=gather();const actual=records.length>=2;if(!actual)records=example;selectedA=Math.min(selectedA,records.length-1);selectedB=Math.min(selectedB,records.length-1);const options=sel=>records.map((r,i)=>`<option value="${i}" ${i===sel?'selected':''}>${esc(r.label)}</option>`).join('');const a=records[selectedA],b=records[selectedB];host.innerHTML=`<div class="record-analysis"><span class="step-label">把觀察放在同一張圖上</span><h3>兩個問題，要讀兩個地方</h3><p>${actual?'以下使用你已完成的實驗紀錄。選擇條件相近的兩組，才能作公平比較。':'還沒有兩筆實驗紀錄，先用模型產生的甲、乙示例；完成前面實驗後會自動換成你的紀錄。'}</p><div class="comparison-select"><label>紀錄 A<select data-a>${options(selectedA)}</select></label><label>紀錄 B<select data-b>${options(selectedB)}</select></label></div>${chart([{label:'A',data:a.curve.map(p=>({x:p.time,y:p.volume}))},{label:'B',data:b.curve.map(p=>({x:p.time,y:p.volume}))}])}<div class="reading-points"><button data-reading="slope"><small>① 前段斜率</small><b>這段有多快？</b><span>讀取前 10 秒平均速率 →</span></button><button data-reading="plateau"><small>② 最後平台</small><b>最後有多少？</b><span>讀取完全反應的總量 →</span></button></div><p class="observation-status" data-reading-note>依序點兩個讀圖位置，找出速度與產量的證據。</p><details class="model-note"><summary>查看曲線數據表</summary><div class="table-scroll"><table><thead><tr><th>紀錄</th><th>0 秒 / mL</th><th>10 秒 / mL</th><th>最終量 / mL</th></tr></thead><tbody>${[a,b].map((r,i)=>`<tr><th>${i?'B':'A'}</th><td>0</td><td>${fmt(at(r.curve,10))}</td><td>${fmt(r.final)}</td></tr>`).join('')}</tbody></table></div></details></div>`;host.querySelector('[data-a]').addEventListener('change',e=>{selectedA=Number(e.target.value);viewed.clear();draw();});host.querySelector('[data-b]').addEventListener('change',e=>{selectedB=Number(e.target.value);viewed.clear();draw();});host.querySelectorAll('[data-reading]').forEach(btn=>btn.addEventListener('click',()=>{viewed.add(btn.dataset.reading);host.querySelector('[data-reading-note]').textContent=btn.dataset.reading==='slope'?`前 10 秒平均速率：A ${fmt(at(a.curve,10)/10,2)} mL/s；B ${fmt(at(b.curve,10)/10,2)} mL/s。這是區間平均值，並非每一秒相同。`:`最終量：A ${fmt(a.final)} mL；B ${fmt(b.final)} mL。${Math.abs(a.final-b.final)<.01?'平台相同，不代表到達的速度相同。':'平台不同，請檢查起始材料與酸是否足量，不能只歸因於快慢。'}`;if(viewed.size===2)record('chart');}));}
 function at(curve,t){if(t>=curve.at(-1).time)return curve.at(-1).volume;const i=curve.findIndex(p=>p.time>=t);if(i<=0)return curve[0].volume;const a=curve[i-1],b=curve[i];return a.volume+(b.volume-a.volume)*(t-a.time)/(b.time-a.time);}
 draw();let n=gather().length;const refresh=()=>{if(gather().length!==n){n=gather().length;draw();}};document.addEventListener('ch4-records',refresh);return()=>document.removeEventListener('ch4-records',refresh);}
 if(id===7){const seen=new Set();host.innerHTML=`<div class="reversible-study"><div class="view-tabs"><button data-reverse="water" aria-pressed="true">① 水的物理類比</button><button data-reverse="chemical" aria-pressed="false">② 真正的化學反應</button></div><div data-reverse-scene></div><p class="virtual-only">NO₂ 有毒：只在虛擬模型中探索。</p></div>`;function show(mode){host.querySelector('[data-reverse-scene]').innerHTML=mode==='water'?`<div class="reverse-panel physical"><div class="water-jar"><div class="water-surface"></div><span>H₂O(l)</span><i>H₂O(g)</i><b>↑　↓</b></div><div><span class="step-label">物理類比，不是化學反應</span><h3>蒸發 ⇌ 凝結</h3><p>液態水可以蒸發，水蒸氣也能凝結。兩邊都還是 H₂O，沒有變成另一種物質。</p><p>這個類比幫助我們想像「兩個方向同時進行」。</p></div></div>`:`<div class="reverse-panel chemical"><div class="molecular-reverse"><div><span class="molecule-no2">N O₂</span><span class="molecule-no2">N O₂</span></div><b>⇌</b><span class="molecule-n2o4">N₂ O₄</span></div><div><span class="step-label">真正的可逆化學反應</span><h3>2NO₂(g) ⇌ N₂O₄(g)</h3><p>正反應：兩個 NO₂ 結合成一個 N₂O₄。<br>逆反應：一個 N₂O₄ 分解成兩個 NO₂。</p><p>適當條件下兩個方向可同時進行；兩側都是 2 個氮原子與 4 個氧原子。</p></div></div>`;}host.querySelectorAll('[data-reverse]').forEach(b=>b.addEventListener('click',()=>{seen.add(b.dataset.reverse);host.querySelectorAll('[data-reverse]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));show(b.dataset.reverse);if(seen.size===2)record('reverse');}));show('water');}
 if(id===10){const truths=[['烈火燃薪，頃刻成燼；風霜蝕鐵，積歲方深。','反應速率','比較同時間的變化量；反應物本性與環境條件會影響快慢。'],['水面雖平，潛流未歇。','動態平衡','正、逆反應以相同速率持續發生，所以各濃度穩定。'],['同沙兩漏，疾徐有別；先盡者，未必多也。','速度、產量與平衡組成','催化劑能加速，但不改變相同條件下的理論產量或平衡組成。']];const seen=new Set();host.innerHTML=`<div class="truths">${truths.map((t,i)=>`<details data-truth="${i}"><summary><span>0${i+1}</span>${t[0]}<b>解開 ↓</b></summary><h3>${t[1]}</h3><p>${t[2]}</p></details>`).join('')}</div><section class="ammonia" data-secret-book hidden aria-live="polite"><span class="step-label">暗格開啟 · 下一段冒險</span><h3>木匣深處的《百工秘卷》</h3><figure class="scene-figure secret-book-figure"><div class="secret-book-art" role="img" aria-label="小葵與阿公打開木匣暗格，驚喜地發現藍布封面的《百工秘卷》。"></div><figcaption>「找到了！」小葵與阿公發現了暗格裡的《百工秘卷》，新的冒險正要展開。</figcaption></figure><p>小葵依紙條的次序，按下火焰、水紋與沙漏刻紋。「喀噠！」匣底薄板鬆開了。兩人掀起暗格，裡面靜靜躺著一本藍布封面的舊書，書名是《百工秘卷》。</p><p>書頁間夾著皇帝的手書：「四坊有難，望二位再施援手。」下方畫著一盞熄滅的燈、一只香囊、一件油污滿布的衣裳，還有幾束不同的纖維。</p><p><b>小葵：</b>「燈油、香料、油污和布料……這本書為什麼把它們放在一起？」</p><p><b>阿公：</b>「翻開第一頁，先看看它們是由什麼組成的。」</p><p>小葵翻開書頁，一個「碳」字映入眼簾。書中的時空門泛起微光，門後正是熟悉的皇城藏書閣。兩人帶著手札踏入門中，新的委託正在等著他們。</p><div class="reaction-equation">第五章｜碳的千面術：皇城萬物修復計畫</div></section><div class="ammonia"><span class="step-label">把規律帶進真實世界</span><h3>製氨工廠，也在解同一道題</h3><div class="reaction-equation">N₂ + 3H₂ ⇌ 2NH₃ + 熱</div><div class="ammonia-grid"><p><b>提高溫度</b>通常讓反應更快，卻降低此放熱反應平衡時的氨比例。</p><p><b>適當催化劑</b>加快接近平衡，但不改變同溫條件下的平衡組成。</p><p><b>選擇操作條件</b>需要兼顧速度、產物比例與實際成本；並非溫度越高越好。</p></div></div>`;host.querySelector('[data-secret-book]').hidden=!state.evidence.includes('truth');host.querySelectorAll('[data-truth]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open){seen.add(d.dataset.truth);if(seen.size===3){record('truth');host.querySelector('[data-secret-book]').hidden=false;}}}));}
 return()=>{};
}
